expression:
local({
  region <- if_else(surveyyear == 2014, id1, subregion)
  paste(surveyyear, countryno, coalesce(as.character(region), "all"), sep = "_")
})

local({
  unit <- na_if(case_when(surveyyear == 2006 ~ cluster, surveyyear == 2014 ~ id2, .default = schoolno), 0)
  region <- if_else(surveyyear == 2014, id1, 0)
  if_else(is.na(unit) | is.na(region), NA_character_, paste(surveyyear, countryno, region, unit, sep = "_"))
})

local({
  use <- na_if(
    case_when(surveyyear == 2002 ~ cannabis12m, surveyyear == 2014 ~ cannabis30d_2, .default = cannabis30d),
    0
  )
  case_when(use >= 2 ~ TRUE, use == 1 ~ FALSE)
})
